import { api } from './authService';

/**
 * FIX : le statut doit etre envoye en UPPERCASE pour correspondre a l'enum Java
 *        ReservationStatus { PENDING, CONFIRMED, CHECKED_IN, CHECKED_OUT, CANCELLED }
 *        Le frontend utilise les valeurs en minuscule (pending, confirmed, checked_in...)
 *
 * FIX 2 : CreateReservationRequest n'a PAS de champ status → la creation est
 *          toujours PENDING cote backend. Pour creer une reservation avec un
 *          statut different, il faut creer puis mettre a jour immediatement.
 */

const toBackendStatus = (status) => {
  if (!status) return null;
  // deja en majuscule
  if (status === status.toUpperCase()) return status;
  const map = {
    pending:     'PENDING',
    confirmed:   'CONFIRMED',
    checked_in:  'CHECKED_IN',
    checked_out: 'CHECKED_OUT',
    cancelled:   'CANCELLED',
  };
  return map[status] ?? status.toUpperCase();
};

const reservationService = {
  /** GET /reservations */
  getAll: async (params = {}) => {
    const { data } = await api.get('/reservations', { params });
    return data?.data ?? data;
  },

  getMyReservations: async () => {
    const { data } = await api.get('/reservations/my');
    return data?.data ?? data;
  },

  getById: async (id) => {
    const { data } = await api.get(`/reservations/${id}`);
    return data?.data ?? data;
  },

  /**
   * POST /reservations
   * CreateReservationRequest : clientId, roomId, checkInDate, checkOutDate, guests, notes
   * IMPORTANT : pas de champ status dans la creation → toujours PENDING au depart
   * Si un statut est selectionne, on fait un update juste apres.
   */
  create: async (payload) => {
    const mapped = {
      clientId:     Number(payload.client_id),
      roomId:       Number(payload.room_id),
      checkInDate:  payload.check_in,
      checkOutDate: payload.check_out,
      guests:       Number(payload.guests) || 1,
      notes:        payload.notes || '',
    };
    const { data } = await api.post('/reservations', mapped);
    const created = data?.data ?? data;

    // FIX : si un statut different de PENDING est demande, on le met a jour
    const requestedStatus = toBackendStatus(payload.status);
    if (created?.id && requestedStatus && requestedStatus !== 'PENDING') {
      try {
        const updatePayload = {
          checkInDate:  payload.check_in,
          checkOutDate: payload.check_out,
          guests:       Number(payload.guests) || 1,
          notes:        payload.notes || '',
          status:       requestedStatus,
        };
        const { data: updated } = await api.put(`/reservations/${created.id}`, updatePayload);
        return updated?.data ?? updated;
      } catch (e) {
        // si le changement de statut echoue, on retourne quand meme la reservation creee
        console.warn('Status update after create failed:', e.message);
      }
    }

    return created;
  },

  /**
   * PUT /reservations/{id}
   * UpdateReservationRequest : checkInDate, checkOutDate, guests, notes, status (optionnel)
   * FIX : status envoye en UPPERCASE
   */
  update: async (id, payload) => {
    const mapped = {
      checkInDate:  payload.check_in,
      checkOutDate: payload.check_out,
      guests:       Number(payload.guests) || 1,
      notes:        payload.notes || '',
    };
    // FIX : convertir le statut en UPPERCASE avant envoi
    const status = toBackendStatus(payload.status);
    if (status) mapped.status = status;

    const { data } = await api.put(`/reservations/${id}`, mapped);
    return data?.data ?? data;
  },

  cancel: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/cancel`);
    return data?.data ?? data;
  },

  checkIn: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/check-in`);
    return data?.data ?? data;
  },

  checkOut: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/check-out`);
    return data?.data ?? data;
  },

  delete: async (id) => {
    const { data } = await api.delete(`/reservations/${id}`);
    return data?.data ?? data;
  },
};

export default reservationService;
